window.DAILY = {"generated_utc": "2026-11-25T09:54:55Z", "date_cn": "2026-11-25", "window_days": 3, "source": "arXiv OAI-PMH/API (cs.CV/cs.RO) · 热度加成: Hugging Face Daily Papers", "note": "所有条目直接来自 arXiv 元数据，未经人工或模型改写；预印本未经同行评审。", "tracks": {"slam": {"name": "SLAM 与状态估计", "papers": [{"id": "2611.32523", "title": "AirLeg: A Robust and Accurate Self-Supervised Visual-Inertial-Leg SLAM System", "authors": ["Kuan Xu", "Tianxin Hu", "Ruofei Bai", "Ruimeng Liu", "Yuefan Hao", "Zeyu Jiang", "Zitong Zhan", "Shenghai Yuan", "Chen Wang", "Lihua Xie"], "abstract": "Visual-inertial-leg (VIL) state estimation offers cost-effective localization for legged robots, adding only a camera to the onboard IMU and joint encoders. However, learning-based leg odometry is limited by its supervision: networks trained in simulation suffer from the sim-to-real gap, while real-world labels require costly sensors or inherit the errors of visual estimates. To address this, we present AirLeg, a self-supervised VIL SLAM system in which vision and leg proprioception improve each other from training to deployment. We pre-train the leg odometry network in simulation and adapt it to the robot without ground truth through imperative learning, where multi-sensor bundle adjustment uses the leg odometry to refine the visual map, which in turn supervises the network. During deployment, the fused estimates adapt the network online. To improve both localization and this supervision, a dual-window estimator fuses vision, IMU, and leg odometry, relates loaded feet to the visually reconstructed terrain through a deformation-aware constraint, and weights the constraints by variance component estimation. AirLeg completes all 17 GrandTour sequences with the lowest average error (0.19 m) among 19 methods. On a low-cost quadruped, it achieves the lowest drift (0.6%) with only 0.5 h of unlabeled data, in real time on an embedded computer.", "published": "2026-11-24", "comment": "19 pages,9 figures", "url": "https://arxiv.org/abs/2611.32523"}, {"id": "2611.22235", "title": "CoSphere-SLAM: Multi-Agent Panoramic Gaussian Splatting SLAM with Spherical Loop Closure", "authors": ["Qi Shao", "Zhihao Cao", "Shuhao Zhai", "Taoyu Wu", "Zhuoxiao Li", "Anh Nguyen", "Long Hu", "Xianzhi Li", "Hong Liang", "Liang Li", "Baoru Huang"], "abstract": "Dense collaborative mapping is essential for search and rescue, building inspection, and warehouse automation, where panoramic cameras capture the entire surroundings in a single frame. Unlike pinhole agents that share views only at similar headings, panoramic agents observe overlapping scenes at any 3D orientation, yet searching full rotations also produces mutually consistent false loop closures across distinct symmetric rooms. Moreover, continuous monocular scale drift splits rigidly merged maps at revisited surfaces, while depth noise at short baselines distorts loop translation directions. To address these challenges, we propose CoSphere-SLAM, the first multi-agent Gaussian splatting SLAM framework for panoramic cameras, whose spherical loop closure aligns spherical features over $\\mathrm{SO}(3)$ via fast Fourier correlation across arbitrary orientations and rejects symmetric false closures through global $\\mathrm{Sim}(3)$ consensus. Building on these closures, directional global optimization solves a per-keyframe $\\mathrm{Sim}(3)$ pose graph with log-scale regularization to correct scale drift while separating optical-flow translation directions from depth-based magnitudes. Finally, omnidirectional Gaussian fusion transforms each Gaussian with its keyframe similarity and renders Gaussians at their maximum ray response to jointly refine poses and maps. Experiments on indoor and cross-session multi-agent panoramic benchmarks demonstrate that CoSphere-SLAM achieves state-of-the-art trajectory accuracy and rendering quality among single-agent and multi-agent methods. Project website: https://cosphere-slam.github.io.", "published": "2026-11-22", "comment": "9 pages, 4 figures, 7 tables. Project website: https://cosphere-slam.github.io", "url": "https://arxiv.org/abs/2611.22235"}, {"id": "2602.07493", "title": "TOM-GS: Robust Thermal Odometry and Mapping with Depth-Guided Gaussian Splatting", "authors": ["Tianhao Zhou", "Shengqian Wang", "Zhihao Zhan", "Yuhang Ming", "Jianzhu Huai"], "abstract": "Thermal infrared cameras offer robustness to darkness, smoke, and illumination changes, making them attractive for robotic deployment in visually degraded environments. However, most existing thermal SLAM systems are geometric and produce sparse maps, while recent learning-based odometry and neural mapping methods are primarily developed for RGB imagery. We present TOM-GS, a monocular thermal odometry and mapping system that integrates learning-based dense tracking with depth-guided 3D Gaussian Splatting for dense reconstruction. Monocular depth priors are used to stabilize thermal odometry and supervise Gaussian geometry, improving scale consistency and robustness in low-texture scenes. Experiments on the RRXIO and VIVID benchmarks show that learned thermal odometry outperforms classical geometric pipelines and that thermal sensing provides improved robustness over RGB under degraded illumination. Furthermore, Gaussian Splatting enables high-quality dense thermal reconstruction in challenging environments.", "published": "2026-11-23", "comment": "9 pages, 4 figures, 3 tables, IROS 2026 Pittsburgh", "url": "https://arxiv.org/abs/2602.07493"}, {"id": "2611.30166", "title": "Toward Open Room-Scale Scanning with Consumer LiDAR via Depth-Inertial Odometry", "authors": ["Minsuk Jang"], "abstract": "Room scanning with consumer LiDAR today depends on ARKit, whose tracking and map update are a black box: an application receives depth and poses but cannot inspect how they were produced, so an error in a scan cannot be traced to its cause. This paper examines whether an open alternative, one whose every stage can be inspected, is feasible on the device. Mobile-LIO is a depth-inertial odometry pipeline that uses the phone's depth and inertial data and no ARKit poses. On seven ScanNet++ iPhone recordings it completed every scene with 0.2-2.0 m deviation from the ARKit-derived reference, where six open-source LiDAR-inertial estimators run as configured for dedicated scanners had at least 4.46 m in 41 of 42 runs (two of the six also failed a noise-free adapter check, and Mobile-LIO has a speed cap they lack; the comparison is not controlled and does not rone 15 Pro Max, a buildwith corrected phone code kept up with the sensor in 14 of 15 replay runs of three 7-13 s recordings; e estimator before thosecorrections. Laser-scanned meshes give the accuracy. Within 3 m, recorded depth differed from the m on three held-out scenes,maps fused with ARKit poses that the dataset scales and aligns to the mesh la a median 1.8-2.3 cm from 17 cm. Because thepipeline is open, the gap could be examined: in the scene with the largest error, noise-free renderefrom 1.97 m to 0.04 m, sorecorded depth, whose error reached 20-54 cm at 5-7 m, contributed alongside the estimator. An open de tracked on phone depth and kept up with the sensor in short phone replays, but it is not yet as accurate as ARKit-pose maps, whicheach only the coarsestUSIBD accuracy level (LOA10); its accuracy on the device was not measured.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.30166"}, {"id": "2611.32335", "title": "GOLD-SLAM: Gaussian-splatting Omnidirectional LiDAR-Depth SLAM", "authors": ["Weicong Zhang", "Yuan Huang", "Yu Zheng", "Lin Chenxiao", "Yingying Li", "Lilong Fan", "Liangdong Zhuang", "Yufan Chen", "Ruiping Liu", "Junwei Zheng", "Jiaming Zhang"], "abstract": "Panoramic cameras capture nearly the entire spherical field of view in a single frame. However, the mismatch between this panoramic coverage and the field of view of LiDAR poses a substantial challenge for panoramic Gaussian splatting SLAM that relies on LiDAR depth priors. We introduce GOLD-SLAM, a Gaussian-splatting Omnidirectional LiDAR-Depth SLAM system that combines high-quality rendering with accurate geometric reconstruction. It performs tracking and mapping in the spherical domain and uses tracked visual features in regions without LiDAR coverage to improve pose estimation. To address insufficient coverage of newly observed surfaces and floating artifacts during incremental mapping, we introduce Depth-Aware Map Extension and Pruning (DAEP). To enable broader evaluation, we collect a new dataset, WHOLE, using a UAV platform across Weak-geometry, High-dynamic, Omnidirectional, Low-light, and Easy scenarios. Extensive experiments on public benchmarks and WHOLE demonstrate competitive rendering quality and improved geometric accuracy relative to perspective systems. Compared with existing panoramic baselines, GOLD-SLAM improves mean PSNR by 5.56-9.10 dB and reduces mean Depth-L1 by 71.9-83.9%. To assess deployment feasibility on resource-constrained platforms such as UAVs, we evaluate an embedded configuration of GOLD-SLAM on a Jetson Orin NX (16 GB), demonstrating online operation at the cost of reconstruction quality.", "published": "2026-11-24", "comment": null, "url": "https://arxiv.org/abs/2611.32335"}, {"id": "2611.29792", "title": "A Cascaded Framework with a Cross-Attention-Guided Mamba-CNN Model for Pre- and Post-Treatment Glioma Segmentation", "authors": ["Siavash Taremi", "Mahmoud Heidari", "Seyed Mohammad Hossein Hashemi", "Mohsen Hooshmand"], "abstract": "Accurate glioma segmentation is vital for diagnosis and follow-up, but manual segmentation is time-consuming, subjective, and variable across interpreters. Gliomas are heterogeneous in size, shape, and location. Deep learning has therefore emerged as a potential solution. CNNs excel at local features but may struggle with long-range dependencies, whereas Vision Transformers capture global context efficiently but incur higher computational complexity. Most previous studies focused on pre-treatment gliomas; post-treatment cases with resection cavities (RCs) remain less explored. This study proposes a Cross-Attention-Guided Mamba-CNN (CMC-Seg) model within a cascaded framework for pre- and post-treatment diffuse glioma segmentation, aiming to balance accuracy and computational cost. Experiments used BraTS 2025 mpMRI of diffuse glioma patients. After preprocessing, a coarse segmentation model extracted tumor-centered patches, which were fed to CMC-Seg for fine-grained segmentation. CMC-Seg was compared with 3D U-Net, SegResNet, SwinUNETR, UNETR, nnFormer, and SegMamba. On the test set, CMC-Seg achieved the highest mean Dice (81.20%) and non-enhancing tumor core (NETC) Dice (77.09%). It also achieved an RC Dice of 78.63% and the lowest 95% Hausdorff distance (HD95; 4.39 mm). Results were comparable to CNN and Mamba baselines and significantly better than Transformer-based baselines (P < 0.05). CMC-Seg required the fewest inference GFLOPs (381.49). Ablation experiments indicated that multi-direction scanning and cross-attention improved performance, particularly for RC (P < 0.05). Grad-CAM explainability experiments showed that CMC-Seg focuses on diagnostically relevant tumor regions.", "published": "2026-11-22", "comment": null, "url": "https://arxiv.org/abs/2611.29792"}, {"id": "2611.30173", "title": "Confidently Lost: Silent Failure and Edge Deployment of Dense Visual SLAM under Photon Starvation", "authors": ["Shrikrishna Bhagirath Rajule", "Srinath Neelamagam", "Aniket Bera"], "abstract": "Dense visual SLAM built on learned two-view geometry is evaluated in good light; in low light it fails silently. Two frames of 9-level quantized noise, no scene at all, give MASt3R-SLAM's network a cross-view geometric self-consistency of 0.936; a real dark frame pair gives 0.935. Starved of structure, the network invents the same geometry for both views and the system trusts the agreement: on a dark sequence it consumes 1,605 frames, emits 7 keyframes, rejects no factor-graph edges and reports full frame rate, while over 95% of the correspondences it accepts violate the ground-truth epipolar geometry. One inflated statistic is read by two subsystems against thresholds in opposite directions, so keyframing starves while relocalization accepts almost every candidate. The same statistic, read at keyframe-pair baselines, separates the confident collapse from working runs on the ETH3D dark sequences without ground truth or extra computation (in-sample). Low-light-adapted weights take tracked trajectories from 1/6 to 5/6, as does retuning two thresholds; neither yields accurate ones, because the adaptation withdraws confidence from wrong geometry rather than finding right geometry. Replayed on a Jetson AGX Orin carried by a legged robot, the mechanism's signature reproduces on the two darkest of four routes, and which of its faces appears varies with route geometry and sensor encoding. The network does not lose confidence in the dark; it manufactures it.", "published": "2026-11-23", "comment": "8 pages, 7 figures. Submitted to IEEE ICRA 2027", "url": "https://arxiv.org/abs/2611.30173"}, {"id": "2611.30741", "title": "Place-Revisit Consistency Evaluation of Reference Poses", "authors": ["Jianzhu Huai", "Yujia Zhang", "Grzegorz Jozkow"], "abstract": "Reference trajectories are widely used to evaluate odometry and simultaneous localization and mapping systems. However, local inconsistencies in benchmark reference poses can bias such evaluations. This paper presents a place-revisit consistency evaluation method for reference poses in mobile sensing datasets. When a platform revisits a previously observed place after a sufficient temporal gap, the relative pose implied by the reference trajectory should agree with relative poses estimated directly from onboard sensors. We instantiate this idea with lidar scan registration and stereo-image pose estimation, and apply it to the KITTI Odometry and SNAIL Radar. The KITTI analysis identifies several revisit regions where the public reference poses disagree with sensor-derived relative poses, with median translation discrepancies up to 6.60 m. Representative point-cloud overlays further localize these discrepancies and support the use of place revisits as a benchmark-validation tool.", "published": "2026-11-23", "comment": "10 pages, 4 figures, 1 table, LBS 2026 Nanjing China", "url": "https://arxiv.org/abs/2611.30741"}, {"id": "2611.31516", "title": "InitFree-SfM: When Initialization-Free Bundle Adjustment meets Learned Structure-from-Motion", "authors": ["Simon Weber", "Mateo de Mayo", "Je Hyeong Hong", "Carl Olsson", "Daniel Cremers", "Ronald Clark"], "abstract": "Initialization-free bundle adjustment (InitFree BA) aims to jointly recover camera poses and scene structure without requiring an initial global estimate. It is a very challenging problem, especially compared to traditional BA where a good estimation is assumed. While recent methods optimize surrogate Object Space Error (OSE) objectives from random initialization, a low objective value does not necessarily yield an accurate reconstruction, revealing a gap between optimization and reconstruction. We show that existing InitFree BA pipelines struggle to produce accurate 3D reconstructions on modern SfM benchmarks, and demonstrate that incorporating learned metric depth substantially improves their practical feasibility. We introduce InitFree-SfM, a complete initialization-free SfM pipeline combining learned correspondences, metric depth, depth-consistent track construction, and joint metric refinement. Within this framework, we propose a simple depth-augmented OSE (dOSE), which complements the directional constraints of OSE by constraining landmark positions along their viewing rays. Our approach substantially outperforms existing InitFree BA methods and achieves competitive accuracy with established SfM pipelines, including on challenging low-overlap image collections. Importantly, our analysis challenges the prevailing emphasis on surrogate objectives in previous InitFree BA research, revealing that geometric constraints play a central role in accurate reconstruction, while OSE-based optimization provides further improvements.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.31516"}, {"id": "2611.29993", "title": "One Size Doesn't Fit All: Input Adaptive Class Activation Mapping for Improved Visual Explanations", "authors": ["Ayesha Sahar", "Tahir Mustafa Madni", "Tehseen Zia", "David Windridge", "Uzair Iqbal Janjua", "Waleed Umar"], "abstract": "Despite their widespread use in tasks such as image classification, object detection and semantic segmentation, the limited interpretability of Convolutional Neural Networks (CNNs) and Vision Transformers (ViTs) can undermine trust and hinder adoption in safety-critical applications. Explainable artificial intelligence (XAI) methods seek to address this by providing human-understandable explanations for model predictions. Class Activation Maps (CAM) constitute one such widely used XAI technique for visualizing discriminative regions. However, existing CAM methods may exhibit limitations in channel weighting, localization, and adaptability across network architectures potentially resulting in noisy or imprecise explanations. To address these issues, we propose ADAPT-CAM, a gradient-based, parameter-adaptive CAM framework. The method combines first-order gradient energy with activation-weighted second-order curvature to derive channel contributions. It further incorporates adaptive local contrast normalization and knee-guided soft channel selection to refine the resulting explanations. Importantly, key parameters are estimated independently for each input, allowing the framework to adapt to variations in feature representations across network architectures. We validate ADAPT-CAM on ImageNet and Oxford 102 Flowers across CNN and ViT architectures. Quantitative results demonstrate competitive or superior performance against established CAM methods across multiple evaluation metrics. In parallel, qualitative comparisons illustrate its ability to highlight discriminative image regions. Further parameter analysis and ablation experiments examine the behaviour and contributions of the individual adaptive components. These findings demonstrate the applicability of ADAPT-CAM across different architectures and datasets.", "published": "2026-11-24", "comment": "20 pages, 5 figures, 5 Tables", "url": "https://arxiv.org/abs/2611.29993"}, {"id": "2611.30184", "title": "OmniSLAM: Evidence-Authorized Revision of Persistent Object Maps", "authors": ["Haoxiang Jie", "Yaoyuan Yan", "Zhiyou Heng", "Liang Li", "Zhaosong Li", "Lifeng Liu"], "abstract": "A new surface observation can extend an object map while contradicting an earlier object assignment. Treating both updates as a single merge can join unrelated objects; keeping all earlier assignments leaves fragmented objects unresolved. We present a revision module that makes these decisions separately. Historical merges require shared-mask evidence to outweigh separate-object explanations across views, including after removal of any one observation. New measured points are assigned through local competition among object seeds supported by image masks. On two preselected KITTI-360 windows, the method improves mean building/car instance AP50:90 from 17.259 to 18.762. On four further spatial holdouts, AP rises from 20.263 to 23.171, although unconditional revision reaches 23.251. Controlled comparisons attribute the gains to protecting existing identities, consolidating selected fragments, and assigning new points locally. The results also show where conservative merge decisions suppress useful updates. A garage recording demonstrates the same revision module on LiDAR--inertial--visual mapping outputs.", "published": "2026-11-24", "comment": null, "url": "https://arxiv.org/abs/2611.30184"}, {"id": "2611.32475", "title": "ROVO: Robust Rotation-Only Visual Odometry for UAVs at Low and Moderate Altitudes", "authors": ["Xiaokai Song", "Li Zhang", "Xichao Teng", "Erting Pan", "Yibin Ye", "Kun Wang", "Leqi Liu", "Guangcheng Dai"], "abstract": "Image noise can confound rotation and translation estimates in monocular visual navigation for unmanned aerial vehicles (UAVs) at low and moderate altitudes, where even small perturbations may cause large errors in translation direction. Inspired by angular cues in long-range visual perception, we propose rotation-only visual odometry (ROVO) for monocular aerial imagery. ROVO estimates pairwise rotations from matched images, robustly averages them over overlapping windows, and aligns consecutive windows through shared frames. By retaining only orientation in the trajectory state, it prevents uncertain landmark depth from propagating to later estimates. In trajectory simulation, sliding-window ROVO achieved a mean orientation error just 10.7% as large as that of the conventional SLAM baseline. On real flight data, ROVO achieved rotation accuracy comparable to ORB-SLAM3 and DPVO under the original Bell412 settings. With a narrower FoV or at higher flight altitude, ROVO reduced relative rotation RMSE by 19.7--69.4% compared with the next-best method in each comparison. Code and simulation tools are available at https://github.com/sssxxxkkkk/ROVO.", "published": "2026-11-24", "comment": null, "url": "https://arxiv.org/abs/2611.32475"}]}, "rep": {"name": "三维表示与重建", "papers": [{"id": "2610.37036", "title": "GraftRay: Physically Based Mesh Insertion into Gaussian Splatting Scenes via Path Tracing", "authors": ["Jinxin Ai", "Matthias Nießner"], "abstract": "We present GraftRay, a unified method for physically consistent insertion of mesh objects into 2D and 3D Gaussian Splatting (2DGS/3DGS) indoor scenes, accounting for lighting interactions between objects and their surroundings. We lift albedo, roughness, metallic and normals from diffusion-based 2D priors onto the Gaussians by back-projection, model windows and lamps as analytic area emitters, and recover their absolute radiance from ordinary LDR captures with a low-dimensional fit over unit-radiance bases. A path tracer over Gaussians and meshes then produces view-consistent shading, interreflections and soft shadows, which are composited onto the original reconstruction by differential rendering, preserving the untouched background. On synthetic, real and generated scenes, GraftRay outperforms recent insertion and inverse-rendering baselines in image fidelity and shadow accuracy at competitive cost, and users prefer its lighting and shadows over those of the baselines.", "published": "2026-11-22", "comment": "8 pages + references, 8 figures, 2 tables", "url": "https://arxiv.org/abs/2610.37036"}, {"id": "2608.04701", "title": "UniView: Large-Baseline View Synthesis via Video Diffusion Models", "authors": ["Wangbo Yu", "Haiyang Zhou", "Chaoran Feng", "Xunyu Zhou", "Li Yuan"], "abstract": "Novel view synthesis from casually captured monocular images and videos offers a practical route to immersive content creation without dedicated multi-view capture. However, the limited viewpoint coverage of such inputs leaves scene geometry insufficiently constrained, restricting the ability of reconstruction-based methods, such as neural radiance fields (NeRF) and 3D Gaussian Splatting (3DGS), to render views far from the observed viewpoints. Generative approaches leverage learned visual priors to synthesize unobserved content, but maintaining geometric consistency and precise camera control remains challenging under large viewpoint changes. We present UniView, a unified framework for large-baseline novel view synthesis and scene generation from monocular images and videos. Central to our approach are an occlusion-aware point cloud renderer and a dual-branch conditioning mechanism. The renderer uses triple reprojection to identify and filter unreliable projections under large viewpoint changes. The conditioning mechanism integrates the resulting geometric guidance with source-view appearance within the video diffusion model, enabling precise camera control while preserving visual details and synthesizing unobserved content. To extend view synthesis to scene generation, we introduce a two-stage generation strategy that decouples viewpoint changes from temporal evolution. This strategy produces dense, synchronized multi-view videos that provide additional supervision for dynamic Gaussian Splatting, enabling more complete 4D generation from monocular observations. Extensive evaluations across static and dynamic scenes demonstrate the effectiveness of UniView in novel view synthesis and scene generation, combining precise camera control with geometric consistency and visual fidelity.", "published": "2026-11-24", "comment": "Project Homepage: https://zhouhyocean.github.io/uniworld-view/ Code: https://github.com/PKU-YuanGroup/UniWorld-View", "url": "https://arxiv.org/abs/2608.04701"}, {"id": "2611.29236", "title": "Complementary Geometry in Gaussian Splatting", "authors": ["Mingle Jiang", "Jikui Zhou", "Chenghan Lyu", "Rui Xu", "Yunke Wang", "Chang Xu"], "abstract": "Gaussian Splatting has achieved high visual quality in novel view synthesis, but the accuracy of its rendered geometry remains a challenge. In particular, the rendered depth is computed as an opacity-weighted average along each ray, which may not correspond to the actual scene surface. In this paper, we observe that depth predictions from different views of the same frozen Gaussian representation exhibit complementary errors, allowing us to improve novel-view geometry using information from other views without modifying the original representation. Based on this observation, we propose REVEAL, a general framework that selectively refines novel-view depth using complementary geometric information. Specifically, we first reproject depth predictions from source views to the target view and combine them using robust multi-view consensus. We then introduce a learned selection mechanism to determine whether the candidate depth is more accurate than the original prediction, based on the expected reduction in depth error. In addition, we introduce RIG, a real-world benchmark captured with synchronized RGB-D cameras, which provides ground-truth depth for evaluating both static and dynamic reconstruction models. Experiments on 6 Gaussian Splatting backbones across 3 benchmarks show that REVEAL consistently improves depth accuracy while maintaining comparable rendering quality.", "published": "2026-11-22", "comment": "14 Pages, supplementary material included", "url": "https://arxiv.org/abs/2611.29236"}, {"id": "2611.31428", "title": "Enhancing Sparse-View Gaussian Splatting with Feed-Forward Priors via Spectral Fusion and Distillation", "authors": ["Weikai Lin", "Jun Dai", "Sheng Zhao", "Junjie Zhao", "Yuhao Zhu"], "abstract": "Gaussian splatting from sparse training views renders high-quality images near training views, but reconstruction quality degrades at distant regions, which are undersampled by the training set. Feed-forward novel view synthesis (NVS) models use strong learned priors to resample the scene from substantially different viewpoints, but they take more than ten times as long to render and produce high-frequency artifacts on out-of-domain scenes. We propose a plug-and-play method that enhances an existing sparse-view Gaussian model with a pretrained feed-forward NVS model. We observe that the two are complementary in the frequency domain: the prior is more accurate at low frequencies, and the Gaussians at high frequencies. The reliability of the prior relative to the Gaussians is inversely proportional to the image frequency, so the optimal fusion weight is a first-order low-pass filter with one parameter that can be fitted. Our key idea is then to intelligently fuse the reliable part of each of the two methods. To remove the slow feed-forward model at render time, we use these fused images as teachers and distill them back into Gaussians, balanced with supervision from input views. Our method improves the quality of various sparse-view Gaussian methods without sacrificing rendering speed, and our analysis works on different prior models. Project page: https://linwk20.github.io/spectral-fusion-gs/", "published": "2026-11-23", "comment": "15 pages. Project page: https://linwk20.github.io/spectral-fusion-gs/", "url": "https://arxiv.org/abs/2611.31428"}, {"id": "2611.32628", "title": "Completion-Aware Compression for Progressive 3D Gaussian Splatting", "authors": ["Reagan Koo", "Yeong-Gyu Kim", "Eun-Seok Ryu"], "abstract": "3D Gaussian Splatting (3DGS) enables high-quality novel-view rendering, but its large scene representations are costly to transmit. Pruning and compression reduce file sizes, yet progressive delivery also requires usable reconstructions before the full scene arrives. Existing progressive representations provide partial scenes, but level-based updates are limited by predefined coding boundaries. This paper presents a progressive 3DGS codec that balances attribute fidelity with the image benefit of making Gaussians available earlier. Its single compact stream supports partial 3D reconstruction and adds newly decoded Gaussians as more bytes arrive. The stream supports fine-grained updates at arbitrary received-byte budgets, without separate encodings or later attribute refinement. At matched complete-file sizes and received bytes, completion-aware allocation improves 1/8 PSNR over attribute-only allocation by 0.48-1.43 dB. The proposed codec compresses original 3DGS representations by 62-88 times while retaining near-reference Full PSNR. Under the evaluated 50-Mbps delivery model, partial reconstruction becomes available in approximately 0.2 s.", "published": "2026-11-24", "comment": "23 pages, 6 main-paper figures and 4 supplementary figures", "url": "https://arxiv.org/abs/2611.32628"}, {"id": "2512.12898", "title": "Beyond Primitive Bloat: High-Fidelity Gaussian Splatting via Coordinate-Convolution Neural Network", "authors": ["Abhinav Kumar", "Tristan Aumentado-Armstrong", "Lazar Valkov", "Gopal Sharma", "Alex Levinshtein", "Radek Grzeszczuk", "Suren Kumar"], "abstract": "Gaussian Splatting (GS) has revolutionized Novel View Synthesis (NVS) with fast training and real-time rendering, yet pushing its fidelity to arbitrary high levels remains an open challenge. We theoretically explain this barrier by proving that discrete Gaussian representations require an exponentially increasing number of primitives to raise training PSNR, which inevitably triggers optimization issues and validation overfitting. To bypass this scaling limit without primitive bloat, we formulate detail recovery as a continuous neural field over coarse renderings and prove that monotonically reducing approximation risk to zero requires jointly leveraging low-fidelity signals, local neighborhood, and coordinate queries. Guided by this result, we augment splatted renderings with an existing Coordinate-Convolution Neural Network (CCNN) that jointly convolves rendered low-fidelity signals with 2D pixel coordinate queries to synthesize residuals. Integrating CCNN into five diverse Gaussian Splatting baselines establishes new state-of-the-art fidelity across NVS benchmarks while preserving real-time rendering speeds with minimal training and storage overhead. Beyond NVS, they also consistently boost performance of 1D/2D regression and 2D super-resolution tasks.", "published": "2026-11-24", "comment": "Project Page: https://abhi1kumar.github.io/qonvolution/", "url": "https://arxiv.org/abs/2512.12898"}, {"id": "2610.36853", "title": "D4GS: Efficient Gaussian Splatting SLAM with Depth Priors", "authors": ["Da Li", "Yihan Zang", "Ivan Viola", "Zeyu Wang", "Dominik Engel"], "abstract": "Achieving high-quality reconstruction and responsive camera tracking remains challenging for monocular RGB Gaussian splatting SLAM under a limited optimization budget. We present an online system that addresses this challenge by combining learned geometric priors with explicit geometric camera tracking, which efficiently performs camera tracking while maintaining the map to keep the predicted depth scale consistent. A frozen depth model serves as a virtual RGB-D sensor, providing depth estimation from monocular video. An explicit geometric solver then estimates camera pose through feature reprojection, and a streaming Gaussian mapper integrates the resulting observations into a dense scene representation. Extensive experiments on indoor and outdoor datasets show that our method significantly improves reconstruction quality over existing approaches, achieving over 10 FPS on a single RTX 4090 and delivering almost twice the throughput of the evaluated fastest prior SLAM systems on the 7-Scenes dataset.", "published": "2026-11-23", "comment": "11 pages, 5 figures", "url": "https://arxiv.org/abs/2610.36853"}, {"id": "2611.31023", "title": "WildAnySplat: Feed-Forward 3D Gaussian Splatting in the Wild", "authors": ["Richard Shaw", "Arthur Moreau", "Athanasios Papaioannou", "Thomas Tanay", "Zhensong Zhang", "Eduardo Pérez-Pellitero"], "abstract": "We present WildAnySplat, a feed-forward 3D Gaussian Splatting framework that enables robust novel-view synthesis from in-the-wild multi-view images. Unlike controlled captures, real-world images often contain multi-view inconsistencies caused by transient occluders, illumination changes, and camera ISP, which degrade the quality of existing feed-forward reconstruction methods. To address this challenge, we introduce a student-teacher framework that learns transient-robust and appearance-consistent 3D representations. A teacher network operates on clean images, while a student processes the corresponding in-the-wild inputs. The teacher provides clean supervision to guide the student toward a consistent canonical representation. Since paired clean and in-the-wild data are scarce, we use a hybrid data strategy, combining real paired captures, synthetic augmentations, and pseudo-clean labels generated from optimization-based reconstructions, bridging the domain gap between synthetic and real-world data. We adopt a transformer architecture with dedicated DPT heads for camera pose, depth, and Gaussian prediction. We additionally predict per-view transient masks to reweight photometric supervision and suppress unreliable Gaussians. To account for cross-view appearance variation, we incorporate a bilateral grid module that models per-image color transformations and enables recovery of a canonical radiance representation. Experiments on challenging in-the-wild benchmarks show that WildAnySplat improves robustness to transient occlusions and appearance variation while retaining the fast inference of feed-forward Gaussian Splatting.", "published": "2026-11-23", "comment": "Accepted to SIGGRAPH Asia 2026 (Conference Papers). Project page: https://wildanysplat.github.io/ ; Supplementary material: https://wildanysplat.github.io/wildanysplat_supp.pdf", "url": "https://arxiv.org/abs/2611.31023"}, {"id": "2605.20044", "title": "OP2GS: Feature-Free Gaussian Splatting with Dual Opacity for 3D Instance Segmentation", "authors": ["Guiyu Liu", "Niklas Vaara", "Janne Mustaniemi", "Juho Kannala", "Janne Heikkilä"], "abstract": "3D Gaussian Splatting (3DGS) provides an explicit and efficient scene representation, but its primitives do not naturally expose object-level identity. Existing methods either learn contrastive per-Gaussian features that need post-hoc clustering, or supervise identity encodings with view-consistent 2D masks. We propose OP2GS, a lightweight object-aware Gaussian representation that augments each primitive with an explicit instance label and a dedicated instance opacity $σ^{*}$, which serves as an instance occupancy field for object-mask rendering. This dual-opacity formulation decouples visual appearance from instance occupancy, so that $σ^{*}$ can be learned and the instance labels can be corrected without touching the appearance parameters $σ$ and $c$. We learn $σ^{*}$ with an instance occupancy loss that follows the standard transmittance-based visibility of 3DGS. A discrete regrouping step then corrects the instance labels using multi-view mask consensus. Since no high-dimensional features are required, OP2GS can be plugged into existing 3DGS training pipelines and applied unchanged to frozen 3DGS assets. On the ScanNet++ validation set with the official class-agnostic protocol, OP2GS improves over OpenSplat3D, the strongest comparable baseline, with both SAM and EntitySeg masks; it is also best on Messy Rooms and, under the Gaga protocol, on Replica, while storing only one scalar and one integer per Gaussian. Code will be released.", "published": "2026-11-24", "comment": "Under review", "url": "https://arxiv.org/abs/2605.20044"}, {"id": "2611.23450", "title": "NIRJALA: Draining the Sea out of Gaussian Splatting with Three-Path Optics and Reversible Physics", "authors": ["Latchan Chhetri", "Aman Kumar"], "abstract": "Water does not just tint an underwater photograph; it rewrites it. Each pixel mixes attenuated scene radiance, backscattered light, and scene light scattered forward on its way to the camera, and many combinations of scene and water explain the same pixels. Most Gaussian-splatting methods for underwater scenes model only the first two effects and remove the water by dividing by a transmission that decays exponentially with range, so their inversion gain grows without bound. We present NIRJALA (Sanskrit for \"without water\"), a 3D Gaussian Splatting framework that recovers water-free appearance and geometry together. TRIVENI, a three-path image formation model, adds a range-saturating forward-scattering term to direct transmission and backscatter; we prove that this keeps the inversion gain bounded at every range and bound how errors in the estimated backscatter and attenuation propagate into the recovered colours. PRATIBIMBA, a reversible physics anchor, ties a flexible neural water model to a ten-parameter physical model in both directions, so scene content cannot hide inside the water. SAMARASA collects the physics-informed objectives, including a range-binned colour prior. To score water removal against ground truth, we built SAJALA (\"with water\"), a 30-scene suite path-traced in Blender Cycles with water-free images, depth, and normals under controlled water colour and turbidity. On SAJALA, NIRJALA raises PSNR from 24.34 to 24.76 dB and lowers depth AbsRel from 0.109 to 0.091 against the strongest baseline; on real SeaThru-NeRF scenes it lowers LPIPS from 0.194 to 0.175 while rendering at 44 FPS. We also discuss where appearance metrics and geometry disagree underwater, and the limits of our evaluation.", "published": "2026-11-24", "comment": "Withdrawn by the authors due to unresolved data provenance and authorization issues affecting the experimental results, tables, and figures in Sections 4--5 (Tables 1--6 and Figures 4--9). The manuscript was submitted prematurely without complete verification", "url": "https://arxiv.org/abs/2611.23450"}, {"id": "2607.01200", "title": "FastBridge: Closing the Model-Based Realization Gap in Safety Filters on 3D Gaussian Splatting for Fast Quadrotor Flight", "authors": ["Dario Tscholl", "Yashwanth Kumar Nakka", "Brian Gunter"], "abstract": "Fast quadrotor flight requires safe obstacle avoidance under tight onboard compute limits. While 3D Gaussian Splatting (3DGS) provides a continuous, geometry-aware scene representation for perception-driven navigation, existing 3DGS safety filters use reduced-order models such as single- and double-integrators that ignore actuator limits and assume commanded accelerations are realized instantaneously. Building on an analytic collision cone barrier for 3DGS, we introduce a nonlinear, actuator-aware safety filter enforced through the full quadrotor dynamics. We derive a high-relative-degree collision cone exponential CBF (ECBF) and a backup CBF whose forward-simulated backup policy provides a certified admissible fallback whenever the QP is infeasible under input constraints. Compared with a state-of-the-art 3DGS safety filter, our approach reduces trajectory jerk by 47% and runs 2.25 times faster. We demonstrate the ECBF in simulation and validate the backup CBF on hardware for real-time navigation in cluttered, perception-derived environments.", "published": "2026-11-24", "comment": "preprint, 8 pages, 4 figures", "url": "https://arxiv.org/abs/2607.01200"}, {"id": "2611.29388", "title": "SpectralGS: Spectral Gaussian Splatting for Unsupervised Spectral Super-Resolution", "authors": ["Qiaoying Qu", "Bin Pan", "Chen Jia", "Haiyang Xu", "Xia Xu", "Zhenwei Shi"], "abstract": "Unsupervised spectral super-resolution aims to recover spectral information from RGB images without paired hyperspectral data. However, the limited spectral information in RGB observations makes learning an effective spatial-spectral representation challenging, requiring the incorporation of structured spectral modeling with sensor imaging. In this paper, we propose SpectralGS, a spectral Gaussian splatting framework comprising two components: Shared Spectral Gaussian Representation and Spectral Response Projection Rendering. The representation module constructs a continuous spatial-spectral representation via shared spectral and local spatial Gaussian primitives, exploiting the low-rank spectral structure of hyperspectral images. The rendering module utilizes the spectral response function (SRF) to apply integral projection to the continuous representation, blending it to generate an RGB image. Consistency between the rendered and observed RGB images provides training supervision. Our main contribution is a Gaussian splatting framework that integrates structured continuous spatial-spectral representation with imaging response-based rendering, enabling unsupervised spectral reconstruction. Extensive experiments demonstrate that our method outperforms current state-of-the-art methods.", "published": "2026-11-22", "comment": null, "url": "https://arxiv.org/abs/2611.29388"}]}, "ff": {"name": "前馈几何（VGGT 一系）", "papers": [{"id": "2611.22244", "title": "PhyVGGT: Feed-Forward Articulated Object Reconstruction from Monocular Videos", "authors": ["Qi Shao", "Zhihao Cao", "Shuhao Zhai", "Anh Nguyen", "Hong Liang", "Liang Li", "Baoru Huang"], "abstract": "Reconstructing an articulated object with its 3D movable parts, joint parameters and unseen articulation states from an uncalibrated monocular video is essential for robot manipulation and interactive digital twins. Existing per-scene optimisation methods require minutes to hours and external depth or camera poses, whereas feed-forward 3D foundation models reconstruct dense point maps in one pass without segmenting movable parts or inferring joints. Even on these monocular point maps, regressing or fitting continuous joints directly fails on casual videos, since cross-frame attention blurs moving part boundaries in deep layers, underestimates motion along the viewing ray and leaves continuous axes ill-conditioned under small opening angles. To address these challenges, we propose PhyVGGT, a single-pass framework on a frozen 3D foundation model that anchors moving-part matching and closed-form joint estimation to the undistorted geometry of the stationary base. First, our Part and Motion Decoder fuses intermediate per-frame tokens with global tokens and references part queries to a static-base query to segment 3D parts, align point maps on the static base and predict learned Bingham priors. Second, our Kinematic Inference Layer fits an orthogonal Manhattan frame to static surface normals, selects the joint axis in closed form under a Bingham posterior combining pairwise motion scatter with the learned priors, and solves a linear system for the hinge pivot to drive unseen states. Trained solely on synthetic data, PhyVGGT achieves state-of-the-art monocular performance across five benchmarks, outperforming FAMOS and monocular ArtiPoint, surpassing posed RGB-D ArtiPoint in median error, and running in 6.8 s per 48-frame video against hours of per-scene optimisation in Articulat3D. Project page: https://phyvggt.github.io.", "published": "2026-11-22", "comment": "10 pages, 5 figures, 7 tables. Project page: https://phyvggt.github.io", "url": "https://arxiv.org/abs/2611.22244"}, {"id": "2611.32297", "title": "MaskedVGGT: Masked Multi-View Transformers Are Scalable 3D Learners", "authors": ["Zichen Zou", "Xiaosong Jia", "Wen-Ming Chen", "Zuxuan Wu", "Yu-Gang Jiang"], "abstract": "Multi-view feed-forward models show strong scalability, but their reliance on costly geometric annotations limits data scaling. Existing 3D self-supervised approaches reduce this reliance through cross-view completion (e.g., CroCo, MuM, Muskie) or novel-view synthesis (e.g., RayZer, E-RayZer), typically learning image representations and cross-view interactions jointly. We argue that learning single image representations from scratch is unnecessary for 3D pretraining methods, as doing so fails to benefit from the continuing advances in 2D foundation models (e.g., DINO, CLIP, frontier VLMs). We introduce MaskedVGGT, which freezes a strong pretrained 2D encoder and pretrains only an added, randomly initialized multi-view transformer, focusing on learning interactions across views. MaskedVGGT pretrains the multi-view transformer through masked self-distillation without annotations: a student predicts targets at masked locations based on complete anchor views and heavily masked remaining views, while an exponential-moving-average teacher provides prediction targets based on unmasked inputs. In experiments across model sizes up to 1B parameters, MaskedVGGT pretraining followed by fine-tuning outperforms single-stage supervised VGGT-$Ω$ training with the same training data, model architecture, and total number of optimization updates. MaskedVGGT also outperforms E-RayZer, CroCo, MuM, and Muskie, providing evidence for the effectiveness of building multi-view pretraining on strong 2D representations. Finally, extending pretraining with additional unlabeled videos further improves generalization, and the learned representations transfer to diverse downstream tasks. These results demonstrate an effective division of learning: reuse strong image representations from 2D pretraining and learn cross-view interactions from unlabeled multi-view data without relying on geometric annotations.", "published": "2026-11-24", "comment": "16 pages, 9 figures, 7 tables. Code is available at https://github.com/zzctmd/MaskedVGGT", "url": "https://arxiv.org/abs/2611.32297"}, {"id": "2611.32491", "title": "X-3DComposer: Feed-Forward 3D Scene Composition with Any Assets from Any Views", "authors": ["Zidian Qiu", "Ancong Wu"], "abstract": "Composing an editable 3D scene from images requires an asset for each object and a layout that places the assets. 3D generation and CAD retrieval now supply the assets, but layout still lacks a general solution: scene generation methods couple it with generation, and pose estimators handle one object at a time and need true-size CAD models, depth, or iterative refinement. We present X-3DComposer, a feed-forward model that predicts the layout separately from asset generation. Given one or more images of a scene, the object masks, and an asset for each object from any source, it jointly predicts the rotation, translation, and per-axis scale of all objects in a single forward pass of about one second. The key idea is to treat objects as views: renders of the assets are processed together with the scene images by a multi-view geometry model adapted from VGGT-$Ω$, and each object pose follows in closed form from the cameras predicted for its renders. Camera intrinsics, camera poses, and depth are optional inputs. When the meshes produced by five scene generation methods are kept fixed and only their layout is replaced, the layouts of X-3DComposer are more accurate than the native layouts of these methods. Compared with the stand-alone layout model SceneMaker, it reduces the scene-level Chamfer distance by 52% on IndoorMix, our test set from six indoor datasets, and by 28% on 3D-FUTURE.", "published": "2026-11-24", "comment": null, "url": "https://arxiv.org/abs/2611.32491"}, {"id": "2606.04493", "title": "Smooth Inliers, Erratic Outliers: Frequency-Aware Mamba for Two-View Correspondence Learning", "authors": ["Zhihua Wang", "Yifeng Gao", "Yunhao Feng", "Rui Pan", "Zhouyuan Ma", "Baiheng Zhao", "Zixing Chen", "Yanping Li", "Yizhang Liu", "Xingjun Ma"], "abstract": "When shown matches between two photographs of the same cathedral, people can tell at a glance which ones are wrong: a window matched to its look-alike jumps against its neighbors, while correct matches shift together. Two-view correspondence learning, also called correspondence pruning, asks a network to make this judgment for thousands of candidate matches, most of which are wrong. Mamba, a fast sequence model, now drives strong pruners, but it reads the matches as a plain sequence, and whether its scan can capture such agreement is unclear. We propose SFMambaNet, which scans the matches cluster by cluster, so that correct matches vary slowly along the sequence while wrong ones stay erratic, and filters the scanned features with learnable frequency-domain gates between its forward and backward passes. On camera pose estimation, outlier removal and homography estimation, we find that SFMambaNet outperforms spatial-domain Mamba baselines with about two million parameters. Contrary to the usual expectation that such gains come from extra capacity, we find that a parameter-free low-pass filter beats point-wise layers as large as the gates. The learned gates turn low-pass on their own and make the scan far less sensitive to how the matches are shuffled. Together, these results show that frequency is a natural language for describing agreement between correspondences, with implications for other sequence models that must read unordered sets, such as point clouds and graphs.", "published": "2026-11-22", "comment": "26 pages, including appendices. Corrected and completed bibliographic metadata in the references", "url": "https://arxiv.org/abs/2606.04493"}, {"id": "2611.30769", "title": "Screening for nonrigidity in structure from motion using projected reprojection residuals", "authors": ["Íñigo Cirauqui-Viloria"], "abstract": "Sparse structure from motion (SfM) assumes a static scene, yet deformation may still yield plausible reconstructions. Reprojection-error summaries discard how errors are arranged across points and views. We propose a diagnostic that first removes residual components explainable by small point and camera adjustments and simple spatial trends that change over time. It then measures alignment with fixed spatial and temporal patterns. The diagnostic uses one estimated SfM reconstruction and provides screening evidence rather than a physical deformation estimate. Across four synthetic tubular families, the diagnostic detected all eight acquisitions with prescribed motion, compared with five or six for summaries of reprojection-error magnitude. Each family's cutoff was the highest static score among the other three families, so the static acquisition with the highest score also screened positive. With the same cutoffs, the diagnostic retained positive detections in 19 of 20 reconstruction variants spanning changes in appearance and reconstruction pipeline, with one numerical abstention. These findings show that the arrangement of reprojection errors across points and views can reveal inconsistencies that their magnitudes alone miss. The four families were known during development, and the transfer variants reused two of them. Within this setting, the diagnostic offers a practical way to flag a plausible reconstruction for closer inspection using only its estimated cameras, 3D points and image observations.", "published": "2026-11-23", "comment": "34 pages including 19 pages of supplementary material. 5 main figures and 5 supplementary figures", "url": "https://arxiv.org/abs/2611.30769"}, {"id": "2611.31478", "title": "Which Way Is Up? Rotated Photos Silently Hurt Multi-View 3D Foundation Models", "authors": ["Yukun Shi", "Minglun Gong"], "abstract": "Multi-view 3D foundation models estimate camera poses and 3D points from a set of photos in one forward pass. Many cameras store a portrait shot sideways, with an orientation tag telling viewers how to turn it, and this tag can be ignored, lost or wrong. We measure how rotated photos affect five such models on three datasets. A few rotated photos lower camera pose accuracy for every model, and the sideways photos already in a standard benchmark do the same. Even the most robust model still loses accuracy. The failure is also silent: the models' confidence does not reliably flag it, and most official image loaders ignore the tag. The fixes we test each correct only part of the problem. These findings call for orientation checks in reconstruction pipelines and benchmarks.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.31478"}, {"id": "2611.31689", "title": "GeoMVGen: Joint Appearance-Geometry Modeling for Multi-View Video Generation in Robotic Manipulation", "authors": ["Qiaoqiao Jia", "Guile Wu", "Dongfeng Bai"], "abstract": "Robotic manipulation requires predicting how robot-object interactions evolve over time, encompassing both visual appearance and scene geometry. In multi-camera settings, such predictions need to capture the evolving 3D scene consistently across viewpoints, while supporting controllable generation under different robot actions and camera configurations. Existing video generation models provide strong priors for visual appearance and motion but typically lack explicit geometric modeling. Meanwhile, recent advances in geometry-aware and multi-view generation have explored joint appearance-geometry modeling and cross-view consistency, yet generating temporally coherent appearance and geometry across multiple viewpoints under robotic manipulation conditions remains challenging. In this work, we propose GeoMVGen, a framework for joint multi-view RGB and pointmap video generation in robotic manipulation. Built on a video diffusion transformer, our framework employs modality-specific adaptation modules to capture the distinct characteristics of appearance and geometry, while using cross-modal residual connections to facilitate information exchange between the two modalities. To establish geometric correspondences across viewpoints, we further introduce a cross-view projection mechanism with complementary geometric supervisions, combining pointmap consistency with geometry foundation model-guided feature alignment. These designs enable controllable generation of temporally evolving multi-view observations with coherent appearance and geometrically consistent scene structures. Extensive experiments on 4D video generation dataset comprising simulated and real-world robotic manipulation scenarios demonstrate that GeoMVGen outperforms state-of-the-art methods in video quality, geometric accuracy, and cross-view consistency.", "published": "2026-11-23", "comment": "Technical Report", "url": "https://arxiv.org/abs/2611.31689"}, {"id": "2611.33157", "title": "PointX: Multi-View Consistent Intrinsics by Querying Surface Points", "authors": ["Miguel Farinha", "Sam Sartor", "Iliyan Georgiev", "Giuseppe Vecchio", "Ronald Clark", "Michael Fischer"], "abstract": "The appearance of a scene is determined by the albedo, roughness, metallicity and normal of every point on its surface, and by the light that reaches it, its irradiance. Recovering these intrinsics from images is ambiguous, and methods that predict them per pixel give the same surface point a different decomposition in every view. We introduce PointX, a simple feed-forward model that predicts intrinsics per 3D surface point instead. A multi-view transformer encodes a set of unposed images, and for any queried surface point, PointX pools the point's tokens across the views in which it appears and decodes the point's intrinsics once. Each point of a 3D reconstruction of the scene, such as a point cloud or a mesh, thus receives a single prediction, which is exactly consistent across views by construction and enables view-consistent relighting and editing. The same model also predicts per-view maps, from one image or many, by querying the point seen at every pixel. These maps agree across views up to the precision of the estimated geometry and correspondences. PointX is significantly more consistent than existing methods, while remaining competitive in accuracy from a single image and improving as views are added. Project page: https://pointx-paper.github.io/", "published": "2026-11-24", "comment": "Project page: https://pointx-paper.github.io/", "url": "https://arxiv.org/abs/2611.33157"}, {"id": "2611.29112", "title": "Bridging Blind Spots With Words: Decentralized Multi-View Spatial Reasoning via Language-Constrained Communication", "authors": ["Soumyabrata Chaudhuri", "Joydeep Ghosh"], "abstract": "As multimodal LLMs (MLLMs) get increasingly used as collaborative partners across embodied robotics, AR/VR, and multi-user systems, spatial reasoning is now often distributed across agents with partial environment visibility, necessitating spatial reasoning integration. Prior work in language-mediated spatial integration is however strictly limited to simplified two-agent scenarios. To address this gap, we first formalize the general problem of decentralized multi-view spatial reasoning, where N agents observe distinct viewpoints, exchange budget-constrained natural language messages, and collaborate to enable a listener to answer spatial queries. We then introduce a novel multi-view spatial benchmark to isolate queries that demand non-trivial multi-view integration. Through an extensive empirical study, we discover that the penalty of restricting decentralized spatial reasoning to natural language with limited budget is far smaller than suggested by prior two-agent literature. Nevertheless, we observe that substantial headroom still remains for multi-agent spatial reasoning in this setting, as evidenced by a significant gap between current centralized performance and an oracle best-of-K ceiling. Moreover, we show that reinforcement learning with credit assignment substantially bolsters the decentralized model, effectively closing the gap with the centralized baseline.", "published": "2026-11-22", "comment": "17 pages, 13 tables, 4 figures", "url": "https://arxiv.org/abs/2611.29112"}, {"id": "2611.29753", "title": "DREAM: Dual-Memory Reasoning for Anticipatory 3D Perception in Autonomous Driving", "authors": ["Sriram Mandalika", "Athira Nambiar"], "abstract": "Autonomous driving systems must not only interpret the current scene but also anticipate perceptual challenges such as occlusions, sparse observations, and recurring failure patterns. However, most existing LiDAR semantic segmentation methods operate in a frame-centric manner, processing each scan independently and discarding past contextual experience, which limits robustness under dynamic scene changes. We propose DREAM, a Dual-memory REAsoning framework for continual LiDAR seMantic segmentation that reframes perception as an experience-driven and anticipatory process. DREAM maintains two complementary memory banks in a strictly online setting: a latent memory that stores compact semantic abstractions of previously observed scenes, and an error memory that records representations associated with uncertain predictions. At each timestep, relevant memory entries are retrieved via cosine similarity and integrated into the feature space through a lightweight modulation mechanism, enabling the model to reinforce consistent semantic patterns while suppressing recurring failure modes. The backbone remains frozen and no past scans are replayed, ensuring computational efficiency and bounded memory growth. Extensive experiments on multiple large-scale LiDAR benchmarks demonstrate that DREAM achieves state-of-the-art performance, with consistent improvements on dynamic and small-scale objects, highlighting the effectiveness of persistent and error-aware memory for robust long-horizon perception.", "published": "2026-11-22", "comment": "CVPR 2026 Workshop", "url": "https://arxiv.org/abs/2611.29753"}, {"id": "2611.30787", "title": "BridgeMVS: Bridging Multi-View Stereo and Monodepth via Bidirectional Dynamic Fusion", "authors": ["Jianfei Jiang", "Haochen Yu", "Qiankun Liu", "Rui Yang", "Hongyuan Liu", "Xianglong Meng", "Jiansheng Chen", "Huimin Ma"], "abstract": "Multi-View Stereo (MVS) and Monocular Depth Estimation (MDE) provide complementary cues for dense 3D reconstruction. While MVS leverages explicit geometry for metric depth, it struggles in challenging regions where feature matching is unreliable. Conversely, MDE provides robust structural priors but typically yields scale-ambiguous results. Existing hybrid methods mainly exploit monocular cues in a unidirectional manner, leaving the mutual enhancement between MDE and MVS insufficiently explored. To address this limitation, we propose BridgeMVS, a unified cascaded multi-stage MVS framework that bridges monocular depth features and multi-view cost volume representations through Bidirectional Dynamic Fusion (BDF). At each stage, BDF performs dynamic mono-to-cost and cost-to-mono updates, where monocular structural features guide cost volume refinement for more robust MVS depth estimation, while multi-view geometric evidence recalibrates monocular representations to improve their metric-scale consistency. Furthermore, the fused monocular and multi-view representations are progressively propagated from coarse to fine stages and constrained by stage-wise relative-scale MDE supervision and metric-scale MVS supervision, enabling cross-branch interactions to benefit subsequent high-resolution depth estimation. In addition, BDF is designed as a plug-and-play module that can be conveniently integrated into existing cascaded MVS frameworks. Extensive experiments demonstrate that BridgeMVS achieves state-of-the-art performance on the DTU, Tanks-and-Temples, and ETH3D benchmarks, while simultaneously boosting the accuracy of monocular depth estimation. Notably, BridgeMVS ranks first on both the Tanks-and-Temples Intermediate and Advanced benchmarks. The source code is available at \\href{https://github.com/JianfeiJ/BridgeMVS}{https://github.com/JianfeiJ/BridgeMVS}.", "published": "2026-11-23", "comment": "Accepted by NeurIPS 2026", "url": "https://arxiv.org/abs/2611.30787"}, {"id": "2611.31140", "title": "HoloSplat: Real-Time Token Streaming for Feed-Forward Human Reconstruction", "authors": ["Chaofan Li", "Qihan Ding", "Shihan Wang", "Zhehao Shen", "Boyu Shen", "Quanyu Chen", "Haoyu Wu", "Lan Xu", "Xin Lou"], "abstract": "Live free-viewpoint video streaming of humans enables immersive telepresence and interactive XR applications. However, this requires reconstructing each frame in real time, transmitting the data within strict bandwidth budgets, and decoding it on lightweight client GPUs. Existing approaches, whether relying on per-frame optimization or feed-forward inference, generate massive 3D Gaussian payloads that exceed practical streaming limits, while aggressive compression severely degrades rendering quality. In this work, we present HoloSplat, a real-time streaming framework for human-centric volumetric video. HoloSplat splits a feed-forward reconstructor before its Gaussian head, introducing a multi-rate streaming codec driven by server-side token compression and client-side token restoration. On the server side, we apply opacity-guided token pruning, PCA-based dimensionality reduction, and lossless geometry coding for token anchors. On the client side, a feature reconstruction hypernetwork is fused into the Gaussian head to recover compression-induced quality loss. Furthermore, we introduce Neural Session Calibration (NSC), which rapidly fine-tunes the Gaussian head online using incoming camera views during a warm-up phase. This resolves quality degradation from novel camera parameters and varying capture conditions with zero per-frame overhead. In our evaluations, HoloSplat averages 32.2 FPS on four RTX 5090 GPUs at 50 Mbit/s. It decodes each frame into 3D Gaussians in 22.1 ms on an RTX 3050 Ti laptop GPU, transmitting 22.8$\\times$ less data than uncompressed float32 Gaussians, while calibrated decoding improves PSNR by 1.050 dB.", "published": "2026-11-23", "comment": "43 pages including supplementary material, 20 figures. Project page: https://heaticy.github.io/HoloSplat/", "url": "https://arxiv.org/abs/2611.31140"}]}, "wm": {"name": "世界模型", "papers": [{"id": "2611.25927", "title": "Fast-JEPA: Advancing the Success-Latency Frontier for Latent World Models", "authors": ["Yao Zhang", "Bin Yu", "Shijie Lian", "Haishan Liu", "Changti Wu", "Yu Wu", "Kai Chen"], "abstract": "Latent world models predict the outcomes of action sequences, but comparing candidate plans through recursive rollout remains expensive at test time. We introduce Fast-JEPA, a latent world model planning framework that advances the success-latency Pareto frontier of predictive search. Fast-JEPA reorganizes predictive computation to support effective action-sequence search at low planning cost. It constructs a goal-directed plan to guide search and directly predicts the outcomes of complete candidates for efficient comparison, avoiding recursive state rollout during refinement. Across PushT, Reacher, Cube, and TwoRoom, Fast-JEPA achieves 96.50% average success rate with 2.41x faster planning than INTACT. Search-budget sweeps show that its competitive success and low latency extend across candidate counts and refinement depths. We further introduce DynaGoal, a benchmark for evaluating world-model planning under dynamic out-of-distribution conditions, execution deadlines, and controlled response delays. Fast-JEPA achieves average success rates of 73.83% on DynaGoal-Shift and 87.67% on DynaGoal-Deadline, demonstrating the practical value of low-latency predictive planning under changing control conditions and execution-time constraints. Our project page is available at https://deepcybo-physai.github.io/Fast-JEPA.", "published": "2026-11-22", "comment": null, "url": "https://arxiv.org/abs/2611.25927"}, {"id": "2611.29609", "title": "JEPA-Shield: Safe Diffusion Planning with Latent World Models via Conformal Shielding", "authors": ["Taekyung Kim", "Ege Yuceel", "Steven Hong", "Georgios Fainekos", "Dimitra Panagou", "Bardh Hoxha"], "abstract": "Latent world models enable planning from images, but their predictions do not directly establish whether a robot will satisfy physical constraints. We present JEPA-Shield, which connects a frozen action-conditioned Joint-Embedding Predictive Architecture (JEPA) world model to task-space safety enforcement. Two downstream models predict relative motion from imagined latent rollouts and decode unsafe geometry from the current image. Split conformal prediction turns end-to-end motion-prediction errors into multi-horizon uncertainty tubes. A backup-based shield checks these tubes against physical constraints and screens both candidate trajectories and final proposals in diffusion-inspired sampling-based model predictive control. Under the stated exchangeability and initial-backup assumptions, we establish probabilistic constraint satisfaction at action-block boundaries for a returned plan executed without replanning. We also introduce VParkBench, with geometric car and tractor-trailer parking tasks and a editable photorealistic Gaussian-splatting environment. In closed-loop evaluation, JEPA-Shield achieves success rates of 84.4%, 82.3%, and 99.0%, respectively, with no observed constraint violations. Ablations show complementary benefits from shielding and uncertainty calibration. The results demonstrate the importance of grounding latent world-model predictions in task-space quantities and explicitly accounting for prediction uncertainty in safety-critical planning.", "published": "2026-11-22", "comment": "Project page: https://www.taekyung.me/jepa-shield", "url": "https://arxiv.org/abs/2611.29609"}, {"id": "2611.30530", "title": "Assembly-JEPA: Using World Models for Fine-Grained Industrial Image Verification", "authors": ["Michael Hollmer", "Andreas Fischer"], "abstract": "Automated verification of industrial assembly processes remains a challenging problem due to substantial visual variability, limited availability of labeled defect data, and the fine-grained nature of many assembly errors. Existing approaches often rely on object detection, CAD models, or supervised classification pipelines, which can struggle to generalize across changing products and assembly configurations. In this work, we propose a novel self-supervised assembly verification framework based on Joint Embedding Predictive Architectures (JEPAs). Starting from the JEPA-based world model LeWorldModel, we investigate how the architecture must be adapted to verify the correctness of fine-grained assembly operations. To this end, we formulate assembly verification as a predictive world modeling task operating on before-and-after observations of assembly processes. Experimental results on industrial assembly tasks demonstrate that the proposed approach reliably detects both fine-grained incorrect assembly states and action-state mismatches, achieving an AUROC of 86.9% on a newly introduced assembly verification dataset. These results indicate that JEPA-based predictive representations constitute a promising foundation for robust and data-efficient industrial assembly verification.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.30530"}, {"id": "2608.29434", "title": "Does Latent Planning Survive Point Clouds? Action-Conditioned JEPA World Models for Geometric Observations and Goals", "authors": ["Fabio F. Oberweger", "Michael Schwingshackl", "Markus Murschitz"], "abstract": "Latent action world models let agents plan new behaviors at test time by predicting how actions change the environment, and joint-embedding predictive architectures (JEPAs) do so by forecasting future latent states rather than pixels. Yet nearly all such models see the world through a camera, even though robotic manipulation is fundamentally geometric: in robotics goals for manipulation are traditionally specified by target object poses, not by images of the object once placed. We ask whether latent planning survives a shift from appearance to geometry, on the observation side as well as on the goal specifications side. To answer this, we extend the stable-worldmodel evaluation platform with simulated LiDAR-style raycast point clouds as a new sensor modality, and adapt three JEPA designs to point clouds: a frozen-encoder model built on Utonia features, a distribution-prior model based on LeWM, and an action-sensitive model based on Delta-JEPA. We further introduce a goal-encoding mechanism that constructs the goal latent from the current latent and a 3D target pose, removing the need for goal images or goal point clouds. A comparative evaluation of the different anti-collapse mechanisms shows that point-cloud world models can match their image-based counterparts, demonstrating that the modality shift from appearance to geometry is achievable. All models are released as open weights with open-source training and inference code, to make world-model planning accessible for LiDAR-driven and pose-directed robotic tasks.", "published": "2026-11-24", "comment": null, "url": "https://arxiv.org/abs/2608.29434"}, {"id": "2611.32113", "title": "PhysRF-WorldJEPA: Transforming Heterogeneous Large Language Models into Manifold-Decoupled Millimeter-Wave Radar World Models", "authors": ["Yicheng Huang", "Feng Ke", "Linhan Chen", "Ziyi Jiang", "Xiu Yin Zhang"], "abstract": "Adapting Large Language Models (LLMs) to millimeter-wave (mmWave) radar enables privacy-preserving, all-weather physical scene understanding across darkness, smoke, and walls. However, standard instruction tuning treats continuous radar streams as static text-like tokens, causing near-random global radar-to-text retrieval and severe physical drift under sensor blackouts. Conversely, coupling pairwise contrastive losses (e.g., SigLIP) directly into the shared backbone improves retrieval but injects $O(B^2)$ repulsive gradients that fracture continuous coordinate manifolds ($R^2 < 0$). We present PhysRF-WorldJEPA, a manifold-decoupled Joint-Embedding Predictive Architecture (JEPA) that separates continuous electromagnetic state prediction from cross-modal language alignment. An unattenuated 1.0x clock anchor and parallel dual-scale RF encoder feed a lean ~3% LoRA LLM trained with two-step state-space EMA-JEPA (Denoise -> Rollout) and sample-axis Batch-VICReg to predict +3.0 s physical states; a stop-gradient alignment head then maps frozen prompt states onto the text hypersphere with false-negative masking. On a 4,541-window tri-domain suite (77/60.25/60 GHz) against 10 baselines, freezing the physical backbone and training only the decoupled head lifts R->T R@10 from 5.95% to 15.01% and improves MedRank from 107.0 to 60.0 while preserving identical physical readout: 3.37 deg ($R^2=+0.961$) blackout +3.0 s torso tilt, 1.89 m ($R^2=+0.679$; 1.19 m/+0.863 at the RF front-end) cluttered UAV altitude, 2.04 m ($R^2=+0.461$) behind-wall NLOS range, 0.9976 virtual-RIS invariance, and 100% fall recall. Across five 0.5B-1.8B LLM families (15 zero-overhead models), World-JEPA improves retrieval and 75%-drop completion in 10/10 runs and blackout tilt in 4/5 (Span-Euc), 2/5 (Scatter), and 5/5 (per-family best) over SFT.", "published": "2026-11-24", "comment": "11 pages, 6 figures, 4 tables", "url": "https://arxiv.org/abs/2611.32113"}, {"id": "2611.32473", "title": "OmniPersist: Persistent Dynamic World Modeling via Coupled Panoramic Evolution", "authors": ["Zhilu Zhang", "Xiaoyu Liu", "Wenxi Liu", "Shengfeng He"], "abstract": "Action-conditioned world models play a vital role in robotics and autonomous driving, yet existing video diffusion models struggle to maintain dynamic object persistence. When the camera turns away and returns, out-of-view moving entities fail to evolve plausibly in latent space, often mutating or vanishing entirely due to bounded perspective views. To resolve this issue, we propose OmniPersist, a unified framework that couples perspective video generation with panoramic evolution within a single-stage diffusion model, without relying on auxiliary models or initial panoramic inputs. To maintain efficiency, we model the panoramic stream at a lower frame rate, bridging both views across space and time via Geometric Anchoring (GeoAnch) for spatial correspondence and Temporal Compensation (TemComp) for temporal aggregation. OmniPersist is agnostic to camera-control architectures, supporting both latent-level and attention-level conditioning. Extensive experiments on a newly constructed dynamic benchmark across image-to-video and video continuation tasks demonstrate consistent gains in visual quality, camera controllability, revisit consistency, and dynamic persistence.", "published": "2026-11-24", "comment": "Project: https://omnipersist.github.io Code: https://github.com/cszhilu1998/OmniPersist", "url": "https://arxiv.org/abs/2611.32473"}, {"id": "2611.32745", "title": "MemAnchorWorld: A Sparse World Model with Horizon-Conditioned Memory Retrieval for Autonomous Driving", "authors": ["Xinyang Jia", "Yuqi Zhang", "Jiakai Wang", "Yahu Yang", "Guandong Pan", "Chao Tong", "Xianglong Liu"], "abstract": "Sparse world models for 4D semantic occupancy forecasting represent scenes with a small set of evolving queries to efficiently predict future geometry and semantics for autonomous driving. However, existing sparse world models face a bottleneck in using historical temporal evidence for long-horizon forecasting. They rely on scene states to carry historical information implicitly, allowing errors to propagate and accumulate across successive forecasting steps and causing geometric and semantic deviations. To address this limitation, we present MemAnchorWorld, a sparse occupancy world model that explicitly retrieves relevant historical geometric and semantic evidence for 4D semantic occupancy forecasting. Inspired by the von Restorff effect, we introduce a forecast-time-conditioned hierarchical dual-path memory-anchor retrieval mechanism. Guided by the effective age and semantic compatibility of historical information, it combines query-level candidate selection with point-level memory-anchor retrieval to provide historical evidence for sparse points at different forecast times. To better use memory anchors and existing features, a point-level residual adapter jointly gated by the task and forecast time separately controls residual corrections to semantics, occupancy confidence, and spatial positions. On Occ3D-nuScenes, MemAnchorWorld achieves an average mIoU of 13.55% and an average IoU of 22.84% across the 1-3 s forecasting horizons, attaining state-of-the-art performance on both metrics.Project page: https://memanchorworld.github.io/", "published": "2026-11-24", "comment": "11 pages, 4 figures, 4 tables", "url": "https://arxiv.org/abs/2611.32745"}, {"id": "2611.32900", "title": "Motion Conditioned World Modeling for Embodied Visual Tracking", "authors": ["Jiahao Zhang", "Xuan Yao", "Junyu Gao", "Changsheng Xu"], "abstract": "World models support embodied decision-making by predicting future environment states. In embodied visual tracking, uncertain target motion and robot-induced viewpoint changes jointly affect visual observations, making future-state prediction challenging. We propose Motion-Conditioned World Modeling, which incorporates predicted target-motion distributions and robot ego-motion into latent state transitions. A Geometry--Progress module jointly models geometric paths and single-step travel distances through shared motion modes and path-conditioned progress distributions. This formulation captures uncertainty in route selection and motion progress while preserving their dependence. Action-induced coordinate transformations express predicted paths in the next robot frame, providing geometrically grounded conditions for future visual-state prediction. Future visual feature reconstruction supervises the motion predictor through the conditioned transition branch, linking explicit motion representations to subsequent observations. The model is jointly optimized with motion likelihood, feature reconstruction, and expert-action supervision, enabling the tracking policy to combine visual context with predictive motion cues.Experiments on three embodied tracking benchmarks demonstrate improved tracking performance and cross-environment generalization with a lightweight $0.5$B backbone.", "published": "2026-11-24", "comment": null, "url": "https://arxiv.org/abs/2611.32900"}, {"id": "2611.33010", "title": "Embodied AI Fails the Mirror Test: How a Simple Mirror Breaks Robot Policies", "authors": ["Xuanchen Liu", "Hejun Zhang", "Boxuan Dong", "Ying Wu", "Heshuai Li", "Wen Gao", "Yonghong Tian", "Weihao Yu"], "abstract": "Can a simple mirror expose the limitations of today's robotic manipulation policies? Inspired by the mirror self-recognition test in animal cognition, we investigate whether robot policies can reliably manipulate physical objects in scenes containing their reflections. We introduce RoboDojo-Mirror, a benchmark built on RoboDojo that preserves task objectives, success criteria, and policy checkpoints while comparing a mirror-free baseline with single-mirror, dual-mirror, and mirrored-tabletop conditions. Across five policies spanning Vision-Language-Action models, World Action Models, and agentic policies, every mirror condition reduces aggregate success rates: averaged over the three conditions, the drop ranges from 10.8 to 56.7 percentage points across policies, and it reaches 62.5 points on the mirrored tabletop. Because a mirror is also a physical obstacle, we compare it against geometrically matched non-reflective panels; 50--88\\% of mirror-specific failures occur without recorded robot--panel contact, so direct collisions alone do not explain the degradation. Trajectory and contact analyses instead reveal recurring behaviors consistent with phantom targeting of reflected objects and spatial mislocalization of real ones. Targeted diagnostics further characterize grasping near reflections, policy-dependent pushing progress, and physical-target interaction under main-camera occlusion. Real-robot experiments with $π_{0.5}$ and FastWAM also show lower overall success rates under the upright-mirror and mirrored-tabletop conditions. These findings reveal a shared vulnerability to reflective environments across diverse robot policies and motivate reflection-aware evaluation of embodied intelligence. Code is available at https://github.com/iPPLab/robodojo-mirror.", "published": "2026-11-24", "comment": "Code: https://github.com/iPPLab/robodojo-mirror", "url": "https://arxiv.org/abs/2611.33010"}, {"id": "2605.23878", "title": "LaMo: Self-Supervised Latent Motion Priors for Physical Realism in Video Generation", "authors": ["Bo Jiang", "Depu Meng", "Yihan Hu", "Yichen Xie", "Tianshuo Xu", "Wei Zhan"], "abstract": "Modern video generators produce visually compelling clips but still struggle with physical and motion consistency, limiting their use as reliable world simulators. Existing remedies often rely on external simulators, teacher models, or curated physics-focused data. We explore a complementary self-supervised direction: extracting motion cues from the unlabeled videos already used to train video diffusion models. We propose LaMo, which formulates a latent motion prior over frame-to-frame latent changes conditioned on the current latent and prompt. This prior is exposed through two lightweight readouts: a macro motion drift used during training as a Motion Drift Loss, and a learned micro motion field used during sampling as Motion Prior Guidance. Both components are plug-and-play with existing video diffusion backbones, requiring no architectural or I/O changes. On VideoPhy, VideoPhy2, and PisaBench, LaMo improves CogVideoX backbones and outperforms recent physics-aware baselines that use external supervision. On VBench, it preserves overall generation quality while improving motion-related dimensions. These results suggest that unlabeled video contains useful motion supervision for improving physical fidelity in modern video diffusion models.", "published": "2026-11-22", "comment": "Project Page: https://lamo-ai.github.io/", "url": "https://arxiv.org/abs/2605.23878"}, {"id": "2611.30120", "title": "AxE: Benchmarking Agent-Environment Generalization of Video World Models via Grounded Events", "authors": ["Haiyu Xu", "Yiyang Chen", "Jiayi Zhou", "Jiaming Ji", "Juntao Dai", "Yaodong Yang", "Boyuan Chen"], "abstract": "Edge cases are not the long tail; they are the norm. An embodied system deployed across changing environments, bodies, objects, and tasks will routinely encounter combinations that were absent from its training data. General-purpose physical intelligence therefore requires world models that reuse prior knowledge, predict consequences, and adapt with little or no additional training. Yet current evaluations of conditional video generation emphasize visual quality, prompt alignment, or isolated physical plausibility, leaving systematic generalization difficult to measure. We introduce AxE Bench, a benchmark that organizes condition changes along eight factors of the acting agent and of its environment, and pairs every original condition with controlled variants that change one side or both. WBench-plus applies the same structure to an existing multi-turn benchmark, pairing each WBench scenario with variants on the environment side, through its world setting or camera behavior, or on the agent side, through its interaction instructions. Additionally, to score generated futures, we develop an evaluation harness that combines vision-language reasoning with targeted computer-vision evidence, converting each video into temporally localized events and comparing generated events with reference events in both time and semantics. We summarize each model with the AxE Score, event Fidelity weighted by its Stability across original-variant pairs. Across twenty models, generated events match reference events far more often in timing than in content: no model exceeds a Fidelity of 13.01, the highest Stability is 0.55, and the highest AxE Score is 7.10. Together, these components turn world-model generalization from an informal aspiration into a falsifiable evaluation program for real and simulated interactions. Our project website can be found at: AxEBench.github.io", "published": "2026-11-23", "comment": "Project page: https://AxEBench.github.io", "url": "https://arxiv.org/abs/2611.30120"}, {"id": "2611.30836", "title": "Can Multimodal Fusion MakeSense for Embodied Vision in Degraded Sensing?", "authors": ["Cheng-Ru Chou", "Shih-Yu Lai", "Pei-Lin Chiang", "Shou-Po Tsai", "Jing-Zhe Huang", "Fukuharu Tanaka", "Hirozumi Yamaguchi", "Bing-Yu Chen", "Yu-Lun Liu", "Hsun-Ping Hsieh"], "abstract": "Embodied vision systems rely on complementary sensors to perceive and act as conditions change. Even models that accept arbitrary sensor subsets can exhibit negative fusion: adding a sensor increases prediction error. We propose MakeSense, a multimodal fusion framework that preserves sensor-specific evidence in private streams and combines information through shared bottleneck tokens. Training pairs full and subset views of the same degraded observations, penalizing higher error with more sensors. Where geometry permits, the distance readout uses range measurements alone, while the rest of the prediction draws on all available inputs. Paired tests across five datasets reveal helpful and harmful sensor additions. MakeSense reduces negative fusion on MM-Fi. With lightweight adapters and per-dataset training, the same design improves UAV localization on MMAUD, cooperative 3D detection on V2X-Real, few-shot pose transfer to RELI11D, and command prediction on Humanoid-Everyday, where a world model trained on the frozen core's outputs forecasts future fused states more accurately than a linear baseline at longer tested horizons. MakeSense supports embodied sensing across human activity, aerial systems, robotics, and autonomous driving.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.30836"}]}}};
